import{_ as i,l as o,o as e,c as s,v as t,p as l,x as r,d as h,i as E,S as A}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"因果树与异质处理效应","description":"","frontmatter":{"title":"因果树与异质处理效应","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/causal-tree-heterogeneity.md","filePath":"quant/causal-tree-heterogeneity.md","lastUpdated":1789023840000}'),p={name:"quant/causal-tree-heterogeneity.md"};function d(u,a,m,c,B,b){const n=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="因果树与异质处理效应" tabindex="-1">因果树与异质处理效应 <a class="header-anchor" href="#因果树与异质处理效应" aria-label="Permalink to &quot;因果树与异质处理效应&quot;">​</a></h1><div class="epigraph"><p>递归划分可以用来估计条件平均处理效应，但分裂必须对估计诚实：用来选分割的样本，不得再用来填叶子里的效应。</p><footer>—— Athey and Imbens, Recursive Partitioning for Heterogeneous Causal Effects, PNAS, 2016</footer></div><p>平均处理效应把一个制度、一次纳入、一次干预收成一个数。研究与产品更常问的是：对谁有效、在哪一类公司或哪一种波动状态下有效。条件平均处理效应 \\(\\tau(x)=\\mathbb{E}[Y(1)-Y(0)\\mid X=x]\\) 把这个问题写成 \\(x\\) 的函数。Athey 与 Imbens 的因果树用递归划分去逼近 \\(\\tau(x)\\)，并引入诚实（honesty）切割，避免普通回归树把噪声差当成异质。Wager 与 Athey 的因果森林把许多这样的树平均起来，给出逐点效应与渐近正态。量化里它适合分析<strong>已识别的处理</strong>在截面或状态上的异质，不适合把「动量最高的那一档」事后叫做处理。与 <a href="/quant/double-machine-learning">DML</a> 的分工是：DML 把平均效应估准，因果树/森林把 \\(\\tau(x)\\) 的形状估出来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>观测数据里每人只看见一个潜在结果。在无混杂与重叠下，\\(\\tau(x)\\) 等于条件均值差 \\(\\mathbb{E}[Y\\mid D=1,X=x]-\\mathbb{E}[Y\\mid D=0,X=x]\\)。普通回归树直接预测 \\(Y\\)，分裂标准是结果的均方误差，叶子里处理组与对照组的差会被「谁更容易进处理组」污染，也会被诚实性缺失放大：同一批样本既决定切在哪、又决定叶子均值，差的方差被低估，异质看起来处处显著。</p><p>金融里处理很少是抛硬币。指数调入偏向大盘与流动性；融券标的偏向有券源的名字；某项监管先落在特定板块。若把这些指定机制留下的差异全部叫做 \\(\\tau(x)\\)，树会把选择描述成效应。问题因此有两层：统计上如何诚实估计条件差；设计上 \\(D\\) 是否在给定 \\(X\\) 后可视为外生。第二层不能靠把树加深来解决。</p><h3 id="诚实分割与「效应的-mse」" tabindex="-1">诚实分割与「效应的 MSE」 <a class="header-anchor" href="#诚实分割与「效应的-mse」" aria-label="Permalink to &quot;诚实分割与「效应的 MSE」&quot;">​</a></h3><p>Athey–Imbens 把样本劈成两半：一半只用来决定树结构（在哪切、切多深），另一半在结构冻结后进入叶子，计算处理组与对照组的均值差。因为叶子估计量不再参与选切点，常规的过拟合乐观被削掉。分裂标准也从结果 MSE 改成处理效应的期望 MSE：优先切那些让两组对比更干净、叶子内效应更异质的方向。变换结果 \\(Y^*=DY/\\pi-(1-D)Y/(1-\\pi)\\)（\\(\\pi\\) 为倾向）把 \\(\\tau(x)\\) 写成对 \\(Y^*\\) 的回归，于是可用回归树的算法，但必须配合诚实与重叠修剪。</p><p><span class="marginnote">叶子太小会让组内处理或对照缺员，条件差没有定义。因果树必须在分裂时检查两组最小样本，而不能只检查总样本。金融截面同一天高度相关，有效样本远小于行数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>单棵诚实因果树。</strong> 预指定处理、结果窗口与控制。倾向可用逻辑回归或 <a href="/quant/gbdt-alpha">GBDT</a> 在训练折内估计，再构造 \\(Y^*\\) 或在叶子里做差。深度、最小叶样本只在诚实的「结构样本」上用交叉验证选；效应样本碰不得超参。输出是分区：每个叶给出 \\(\\hat\\tau\\) 与置信区间。适合向投委会解释「效应集中在小盘 / 高换手」这类粗异质。</p><p><strong>因果森林。</strong> Wager–Athey（2018）对诚实因果树做子采样并平均，得到 \\(\\hat\\tau(x)\\)。Athey、Tibshirani 与 Wager 的广义随机森林（GRF）把同一套局部加权思想推广到分位数、工具变量。逐点标准误来自无限阶 U 统计量的渐近，不是普通 bootstrap 随便重抽交易日。时间序列上子采样应抽时间块，避免把同一段行情切碎后假装独立。</p><h3 id="量化里三条合法处理" tabindex="-1">量化里三条合法处理 <a class="header-anchor" href="#量化里三条合法处理" aria-label="Permalink to &quot;量化里三条合法处理&quot;">​</a></h3><ol><li><strong>准实验。</strong> 指数定期调入、涨跌停制度变更、融券名单调整，指定规则可写成 \\(X\\) 的函数加一个残差。残差越大，重叠越好。应报告指定方程，而不是只报森林的变量重要性。</li><li><strong>随机化或交错推出。</strong> 交易所或券商若真有试点与对照组，因果树最干净。这类数据少，但不必用机器学习去「发现」处理。</li><li><strong>连续处理的局部。</strong> 某项持仓比例、某项税收，在重叠好的区域估剂量响应。叶子变成局部线性，而不是简单双均值。</li></ol><p>把因子排序的最高分位叫做 \\(D=1\\)、其余叫做对照，违反重叠与外生：处理几乎是 \\(X\\) 的确定性函数，\\(\\tau(x)\\) 退化成「高分组与低分组的收益差」，那是组合排序，见<a href="/quant/long-short-sort">单因子多空</a>，不是异质处理效应。</p><p><span class="marginnote">诚实分割会牺牲效率：一半数据不进效应估计。因果森林用子采样部分挽回。不要为了「叶子更显著」而取消诚实——那正是 Athey–Imbens 要禁止的用法。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>回归树切的是 \\(Y\\) 的异质，因果树切的是 \\(Y(1)-Y(0)\\) 的异质。二者只在处理随机且方差齐时大致重合。若处理组更常出现在高波动名字里，预测 \\(Y\\) 的树会反复用波动去切，叶子差反映的是波动，不是处理。变换结果把目标对准 \\(\\tau\\)，诚实再把选切点的搜索与填数字分开，于是「看起来到处都有异质」的假阳性下降。</p><p>森林的逐点估计是对邻近观测的加权差：权重由有多少棵树把目标 \\(x\\) 与观测 \\(i\\) 分进同一叶决定。它是自适应的 k 近邻，度量由因果分裂学出来。与线性交互项相比，不必预先写 \\(D\\times x_k\\)；与 <a href="/quant/double-machine-learning">DML</a> 的平均效应相比，它不把 \\(\\tau(x)\\) 积掉。代价是：重叠差的区域权重集中在极少对照上，区间会诚实变宽——变宽是功能，不是缺陷。</p><h3 id="和-shap、分样本-ic-的差别" tabindex="-1">和 SHAP、分样本 IC 的差别 <a class="header-anchor" href="#和-shap、分样本-ic-的差别" aria-label="Permalink to &quot;和 SHAP、分样本 IC 的差别&quot;">​</a></h3><p><a href="/quant/shap-factor-attribution">SHAP</a> 解释的是预测模型 \\(f(x)\\) 的输出如何分摊到特征，不估计潜在结果差。分样本 IC 是预测表现的切片，也没有对照。因果树要求一个处理变量和一套识别假设。用 SHAP 或 IC 切片去讲「对小盘更有效」，在预测故事里可以，在因果故事里不行。反过来，把因果森林的 \\(\\hat\\tau(x)\\) 当下一期 alpha 去排序，是把条件效应当成可交易预测，通常既无时点对齐，也无执行模型。</p><p>多重检验仍然在。试了很多处理定义、很多 \\(X\\)、很多叶子解释之后，个别叶子的显著会被挑选出来。预先指定要报告的异质轴（规模、行业、波动、拥挤），其余只作探索，并在文中标明。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>无混杂在公司金融与市场微观结构里很少恰好成立。能做的是：把指定机制写进 \\(X\\)、用工具变量森林、或把结论降级为「条件差的描述」。不要用因果森林的软件默认值在全样本拟合一次，再把最大的叶子写成论文标题。结果窗口若覆盖处理之后的价格压力与长期基本面，应拆开短窗与长窗，否则树会把暂时冲击与永久效应混在同一 \\(\\tau\\) 里。</p><p>A 股停牌、涨跌停使部分 \\(Y\\) 截断，叶子均值被不可交易日扭曲。处理发生在不可交易窗口时，应把这些观测剔除或改用首次可交易收益。截面相关使叶子的名义样本量骗人，推断以时间聚类或按日聚合后再进森林更稳。GRF 的调参（<code>mtry</code>、子样本比例、诚实比例）必须在预先切开的验证时间块上进行，禁止看测试期的异质图再改。</p><p><span class="marginnote">变量重要性在因果森林里表示「常被用来切效应」，不是「该特征是调节的经济机制」。共线的市值与流动性会互相替代。报告时应给出预先指定轴上的 \\(\\tau(x)\\) 曲线，而不是一张 importance 排行榜。</span></p>',26)),(e(),l(A,null,{default:r(()=>[E(n,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20H%5B%22%E8%AF%9A%E5%AE%9E%E5%88%87%E5%88%86%22%5D%0A%20%20H%20--%3E%20STR%5B%22%E7%BB%93%E6%9E%84%E6%A0%B7%E6%9C%AC%3A%20%E5%8F%AA%E5%86%B3%E5%AE%9A%E5%88%87%E7%82%B9%22%5D%0A%20%20H%20--%3E%20EST%5B%22%E6%95%88%E5%BA%94%E6%A0%B7%E6%9C%AC%3A%20%E5%8F%AA%E5%A1%AB%E5%8F%B6%E5%AD%90%20tau%22%5D%0A%20%20STR%20--%3E%20TREE%5B%22%E5%9B%A0%E6%9E%9C%E6%A0%91%E7%BB%93%E6%9E%84%22%5D%0A%20%20TREE%20--%3E%20EST%0A%20%20EST%20--%3E%20TAU%5B%22%E5%90%84%E5%8F%B6%20%2F%20%E9%80%90%E7%82%B9%20tau(x)%22%5D%0A%20%20ID%5B%22%E6%97%A0%E6%B7%B7%E6%9D%82%E4%B8%8E%E9%87%8D%E5%8F%A0%22%5D%20--%3E%20TAU%0A%20%20TAU%20--%3E%20REP%5B%22%E9%A2%84%E6%8C%87%E5%AE%9A%E8%BD%B4%E4%B8%8A%E7%9A%84%E5%BC%82%E8%B4%A8%E6%9B%B2%E7%BA%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Athey 与 Imbens 的因果树估计 \\(\\tau(x)\\)，用诚实分割避免选切点与填叶子共用样本造成的假异质。</li><li>Wager–Athey 因果森林与 GRF 把诚实树平均成逐点效应，适合已识别处理的异质，而不是因子排序的事后贴标签。</li><li>分裂对准处理效应的 MSE，而不是结果的 MSE；重叠差时区间变宽是必要的。</li><li>指定机制、点-in-time 控制、时间块验证与预先指定的异质轴，比森林深度更决定结论是否可写进研究。</li><li>出处：Athey and Imbens, <em>PNAS</em>, 2016；Wager and Athey, <em>Journal of the American Statistical Association</em>, 2018；Athey, Tibshirani and Wager, <em>Annals of Statistics</em>, 2019。</li></ul>',2))])}const f=i(p,[["render",d]]);export{x as __pageData,f as default};
